    return ' '.join(text.split())

def compress(text):
    out, count = [], 1
    for i in range(1, len(text) + 1):
        if i < len(text) and text[i] == text[i - 1]:
            count += 1
        else:
            out.append(f'{text[i - 1]}{count}' if count > 1 else text[i - 1])
            count = 1
    return ''.join(out)

