def encode(s):
    out, count = [], 1
    for i in range(1, len(s) + 1):
        if i < len(s) and s[i] == s[i - 1]:
            count += 1
        else:
            out.append(s[i - 1] + (str(count) if count > 1 else ''))
            count = 1
    return ''.join(out)

def decode(s):
    out, i = [], 0
    while i < len(s):
        ch, num, i = s[i], '', i + 1
        while i < len(s) and s[i].isdigit():
            num, i = num + s[i], i + 1
        out.append(ch * int(num or 1))
    return ''.join(out)

