import re
from collections import Counter

STOP = {'is', 'a', 'of', 'and', 'the', 'to', 'in', 'for', 'on'}

def normalize(text):
    return ' '.join(re.sub(r'[^a-z0-9\s]', ' ', text.lower()).split())

def search(text, keyword):
    pos, start = [], 0
    while (i := text.find(keyword, start)) != -1:
        pos.append(i)
        start = i + 1
    return pos

def analysis(text):
    clean = normalize(text)
    words = clean.split()
    freq = Counter(w for w in words if w not in STOP)
    duplicates = sorted({w for w, n in Counter(words).items() if n > 1})
    return {
        'clean': clean,
        'top': freq.most_common(3),
        'duplicates': duplicates,
        'sentences': [s.strip() for s in re.split(r'[.!?]', text) if s.strip()],
    }

sample = 'Data science needs data. Data cleaning, and data validation is step one!'
print(search(normalize(sample), 'data'))
print(analysis(sample)['top'])
print(analysis(sample)['duplicates'])

import json, logging, re
from collections import Counter
from dataclasses import dataclass, field
from difflib import SequenceMatcher

logging.basicConfig(level=logging.WARNING, format='%(levelname)s:%(message)s')

@dataclass
class TextConfig:
    min_word_len: int = 3
    top_n: int = 3
    stop: set = field(default_factory=lambda: {'the', 'and', 'for', 'with', 'from', 'that'})


def normalize(text, cfg):
    if not isinstance(text, str):
        raise TypeError('document must be a string')
    words = re.sub(r'[^a-z0-9\s]', ' ', text.lower()).split()
    return [w for w in words if len(w) >= cfg.min_word_len]


def keywords(docs, cfg):
    tokens = [w for d in docs for w in normalize(d, cfg) if w not in cfg.stop]
    return Counter(tokens).most_common(cfg.top_n)


def similarity(doc, docs):
    return sorted(((round(SequenceMatcher(None, doc, d).ratio(), 3), i) for i, d in enumerate(docs)), reverse=True)


def report(docs, cfg):
    if not docs:
        logging.warning('empty corpus — returning empty report')
        return {'documents': 0, 'vocabulary': 0, 'keywords': [], 'avg_tokens': 0}
    token_lists = [normalize(d, cfg) for d in docs]
    vocab = {w for t in token_lists for w in t}
    return {
        'documents': len(docs),
        'vocabulary': len(vocab),
        'keywords': keywords(docs, cfg),
        'avg_tokens': round(sum(len(t) for t in token_lists) / len(docs), 2),
    }


cfg = TextConfig()
docs = [
    'Retrieval augmented generation grounds answers in retrieved context.',
    'Vector databases store embeddings for similarity search over documents.',
    'Embeddings enable similarity search when retrieval needs semantic matching.',
]
print(json.dumps(report(docs, cfg)))
print(similarity(docs[1], docs))
